        "userFacingName": "Built-in VPN Messaging (Evergreen)",
        "userFacingDescription": "Onboarding CFRs for the built-in VPN",
        "featureIds": [
          "fxms-message-10"
        ],
        "isRollout": true,
        "localizations": {
          "da": {
            "ipprotection-not-now-dropdown-menuitem": "Ikke nu",
            "ipprotection-no-thanks-dropdown-menuitem": "Nej tak",
            "ipprotection-feature-introduction-link-text-3": "Få ekstra privatliv ved at vælge mellem flere placeringer, så du kan skjule, hvor du browser.",
            "ipprotection-feature-introduction-text-summer-promo": "Slå funktionen til for at beskytte dit privatliv bedre på nettet. Få ubegrænset båndbredde og flere placeringer at browse fra. Fra nu og indtil den 31. august."
          },
          "de": {
            "ipprotection-not-now-dropdown-menuitem": "Nicht jetzt",
            "ipprotection-no-thanks-dropdown-menuitem": "Nein, danke",
            "ipprotection-feature-introduction-link-text-3": "Holen Sie sich Extra-Privatsphäre und wählen Sie aus mehreren Standorten, um Ihren tatsächlichen Standort zu verstecken.",
            "ipprotection-feature-introduction-text-summer-promo": "Aktivieren Sie es, um privater zu surfen. Holen Sie sich unbegrenzte Bandbreite und mehr Standorte, von denen aus Sie surfen können. Jetzt bis zum 31. August"
          },
          "fi": {
            "ipprotection-not-now-dropdown-menuitem": "Ei nyt",
            "ipprotection-no-thanks-dropdown-menuitem": "Ei kiitos",
            "ipprotection-feature-introduction-link-text-3": "Paranna yksityisyyttäsi valitsemalla useista eri sijainneista, jotta selaustietosi pysyvät salassa.",
            "ipprotection-feature-introduction-text-summer-promo": "Laita se päälle pitääksesi selaustietosi yksityisinä. Rajaton kaistanleveys ja uusia sijainteja, joista valita. Nyt 31. elokuuta asti."
          },
          "fr": {
            "ipprotection-not-now-dropdown-menuitem": "Plus tard",
            "ipprotection-no-thanks-dropdown-menuitem": "Non merci",
            "ipprotection-feature-introduction-link-text-3": "Profitez d’encore plus de confidentialité en choisissant un emplacement parmi tous ceux disponibles pour masquer l’endroit depuis lequel vous naviguez.",
            "ipprotection-feature-introduction-text-summer-promo": "Activez-le pour protéger votre navigation. Profitez d’une bande passante illimitée et d’un choix encore plus large d’endroits depuis lesquels naviguer. Dès aujourd’hui et jusqu’au 31 août."
          },
          "it": {
            "ipprotection-not-now-dropdown-menuitem": "Non adesso",
            "ipprotection-no-thanks-dropdown-menuitem": "No grazie",
            "ipprotection-feature-introduction-link-text-3": "Aumenta la tua privacy scegliendo tra varie località per non svelare da dove navighi.",
            "ipprotection-feature-introduction-text-summer-promo": "Attivala per navigare in modo più riservato. Goditi una banda illimitata e più località da cui navigare. Da oggi fino al 31 agosto."
          },
          "ja": {
            "ipprotection-not-now-dropdown-menuitem": "後で",
            "ipprotection-no-thanks-dropdown-menuitem": "いいえ、結構です",
            "ipprotection-feature-introduction-link-text-3": "複数の場所から選んで、ブラウズしている場所を秘密にすることで、プライバシーを保護しましょう。",
            "ipprotection-feature-introduction-text-summer-promo": "オンにしてブラウジング活動のプライバシーを守りましょう。帯域幅は無制限で、より多くの地域が選べます。今から 8 月 31 日まで。"
          },
          "nl": {
            "ipprotection-not-now-dropdown-menuitem": "Niet nu",
            "ipprotection-no-thanks-dropdown-menuitem": "Nee bedankt",
            "ipprotection-feature-introduction-link-text-3": "Kies uit verschillende locaties om te verbergen waar u surft, voor extra privacy.",
            "ipprotection-feature-introduction-text-summer-promo": "Schakel deze functie in om uw privacy beter te beschermen. Profiteer van onbeperkte bandbreedte en meer locaties om uit te navigeren. Nu tot 31 augustus."
          },
          "pl": {
            "ipprotection-not-now-dropdown-menuitem": "Nie teraz",
            "ipprotection-no-thanks-dropdown-menuitem": "Nie, dziękuję",
            "ipprotection-feature-introduction-link-text-3": "Zyskaj więcej prywatności, ukrywając się w jednej z wielu lokalizacji.",
            "ipprotection-feature-introduction-text-summer-promo": "Włącz, aby zachować więcej prywatności w internecie. Zyskaj nielimitowaną przepustowość i większy wybór lokalizacji. Od teraz do 31 sierpnia."
          },
          "th": {
            "ipprotection-not-now-dropdown-menuitem": "ไม่ใช่ตอนนี้",
            "ipprotection-no-thanks-dropdown-menuitem": "ไม่ ขอบคุณ",
            "ipprotection-feature-introduction-link-text-3": "รับ ความเป็นส่วนตัวเพิ่มขึ้น ด้วยการเลือกจากหลากหลายตำแหน่งที่ตั้งเพื่อซ่อนตำแหน่งการท่องเว็บของคุณ",
            "ipprotection-feature-introduction-text-summer-promo": "เปิดใช้งานเพื่อให้การท่องเว็บของคุณเป็นส่วนตัวยิ่งขึ้น รับแบนด์วิดท์ไม่จำกัด และตำแหน่งที่ตั้งเพิ่มเติมเพื่อใช้ท่องเว็บ ตั้งแต่วันนี้จนถึง 31 สิงหาคม"
          },
          "en-CA": {
            "ipprotection-not-now-dropdown-menuitem": "Not now",
            "ipprotection-no-thanks-dropdown-menuitem": "No thanks",
            "ipprotection-feature-introduction-link-text-3": "Get extra privacy by choosing from multiple locations to hide where you browse",
            "ipprotection-feature-introduction-text-summer-promo": "Turn it on to keep your browsing more private. Get unlimited bandwidth and more locations to browse from. Now until August 31."
          },
          "en-GB": {
            "ipprotection-not-now-dropdown-menuitem": "Not now",
            "ipprotection-no-thanks-dropdown-menuitem": "No thanks",
            "ipprotection-feature-introduction-link-text-3": "Get extra privacy by choosing from multiple locations to hide where you browse",
            "ipprotection-feature-introduction-text-summer-promo": "Turn it on to keep your browsing more private. Get unlimited bandwidth and more locations to browse from. Now until August 31."
          },
          "en-US": {
            "ipprotection-not-now-dropdown-menuitem": "Not now",
            "ipprotection-no-thanks-dropdown-menuitem": "No thanks",
            "ipprotection-feature-introduction-link-text-3": "Get extra privacy by choosing from multiple locations to hide where you browse",
            "ipprotection-feature-introduction-text-summer-promo": "Turn it on to keep your browsing more private. Get unlimited bandwidth and more locations to browse from. Now until August 31."
          },
          "es-ES": {
            "ipprotection-not-now-dropdown-menuitem": "Ahora no",
            "ipprotection-no-thanks-dropdown-menuitem": "No, gracias",
            "ipprotection-feature-introduction-link-text-3": "Disfrute de privacidad extra eligiendo entre varias ubicaciones para ocultar desde dónde navega.",
            "ipprotection-feature-introduction-text-summer-promo": "Actívela para navegar con más privacidad. Disfrute de un ancho de banda ilimitado y de más ubicaciones desde las que navegar. Ahora hasta el 31 de agosto."
          },
          "es-MX": {
            "ipprotection-not-now-dropdown-menuitem": "Ahora no",
            "ipprotection-no-thanks-dropdown-menuitem": "No, gracias",
            "ipprotection-feature-introduction-link-text-3": "Obtén privacidad adicional eligiendo entre distintas ubicaciones para ocultar dónde navegas.e",
            "ipprotection-feature-introduction-text-summer-promo": "Actívala para que tu navegación sea más privada. Obtén ancho de banda ilimitado y más ubicaciones para navegar. A partir de ahora y hasta el 31 de agosto."
          },
          "pt-PT": {
            "ipprotection-not-now-dropdown-menuitem": "Agora não",
            "ipprotection-no-thanks-dropdown-menuitem": "Não, obrigado",
            "ipprotection-feature-introduction-link-text-3": "Obtenha mais privacidade ao escolher entre várias localizações para ocultar onde navega.",
            "ipprotection-feature-introduction-text-summer-promo": "Ligue-a para manter a sua navegação mais privada. Obtenha largura de banda ilimitada e mais localizações para navegar. Agora até 31 de agosto."
          },
          "sv-SE": {
            "ipprotection-not-now-dropdown-menuitem": "Inte nu",
            "ipprotection-no-thanks-dropdown-menuitem": "Nej tack",
            "ipprotection-feature-introduction-link-text-3": "Förbättra integriteten genom att välja bland flera platser för att dölja var du surfar.",
            "ipprotection-feature-introduction-text-summer-promo": "Aktivera den för att göra ditt surfande mer privat. Få obegränsad bandbredd och fler platser att surfa från. Nu fram till 31 augusti."
          },
          "ja-JP-macos": {
            "ipprotection-not-now-dropdown-menuitem": "後で",
            "ipprotection-no-thanks-dropdown-menuitem": "いいえ、結構です",
            "ipprotection-feature-introduction-link-text-3": "複数の場所から選んで、ブラウズしている場所を秘密にすることで、プライバシーを保護しましょう。",
            "ipprotection-feature-introduction-text-summer-promo": "オンにしてブラウジング活動のプライバシーを守りましょう。帯域幅は無制限で、より多くの地域が選べます。今から 8 月 31 日まで。"
          }
        },
