        "slug": "client-side-sampling-of-performance-metrics-fixed",
        "lastSeen": "2026-09-08T18:07:02.986Z",
        "source": "rs-loader",
        "active": true,
        "prefs": [],
        "branch": {
          "slug": "control",
          "ratio": 1,
          "feature": {
            "value": {},
            "enabled": false,
            "featureId": "this-is-included-for-desktop-pre-95-support"
          },
          "features": [
            {
              "value": {
                "gleanMetricConfiguration": {
                  "metrics_enabled": {
                    "fog.ipc.buffer_sizes": false,
                    "ssl_handshake.result": false,
                    "wr.time_to_render_start": false,
                    "javascript.gc.minor_time": false,
                    "wr.rasterize_glyphs_time": false,
                    "paint.build_displaylist_time": false,
                    "wr.texture_cache_update_time": false,
                    "ssl_handshake.result_first_try": false,
                    "cert.validation_success_by_ca_2": false,
                    "ssl_handshake.result_ech_grease": false
                  }
                }
              },
              "enabled": true,
              "featureId": "gleanInternalSdk"
            }
          ],
          "firefoxLabsTitle": null
        },
        "userFacingName": "Client Side Sampling of Performance Metrics (fixed metric names)",
        "userFacingDescription": "Mozilla can collect less telemetry data from certain parts of the browser and obtain the same signal to reliably monitor browser performance. This rollout samples an initial set of heavy metrics at 10%, so we can save on storage and processing while maintaining the accuracy of our analysis.\nThis rollout fixes the metric names on the configuration to use <category>.<name> format.",
        "featureIds": [
          "gleanInternalSdk"
        ],
        "isRollout": true,
        "localizations": null,
        "isFirefoxLabsOptIn": false,
        "firefoxLabsTitle": "",
        "firefoxLabsDescription": "",
        "firefoxLabsDescriptionLinks": null,
        "firefoxLabsGroup": "",
        "requiresRestart": false
      },
